import java.util.Vector;

public class Pila {
    private Vector<Integer> dati = new Vector<>();

    public void push(int x) {
        dati.add(x);
    }

    public int pop() {
        return dati.remove(dati.size() - 1);
    }
}

public class Main {
    public static void main(String[] args) {
        Pila p = new Pila();
        p.push(3);
        p.push(6);
        System.out.println(p.pop());
        System.out.println(p.pop());
    }
}
